// QA-621 (R1.108; Lead 11's ruling on #2716, P-294 Option C): the simulated persona door is scaffolding, so in a production
// configuration it must make no client. This suite boots one isolated copy twice on the same database:
//   1. PLATFORM_ENVIRONMENT=local: the configured sample is loaded and the Open a case dialog's body (no clientId) opens a
//      case with a new client through the persona route: the control (the body is valid, the door is open locally).
//   2. PLATFORM_ENVIRONMENT=production (every required setting generated by this run, never a real key; no staff sign-in
//      configured): the same body on POST /api/runtime/cases and Demo › Sample case are refused 403
//      SIMULATED_PERSON_REFUSED with nothing written, and the signed-in door (POST /api/runtime/clients/:id/open-case)
//      asks for a staff session (401).
//   3. A sweep of the application code: a client row is written only by clients.ts newClient (called only by
//      Runtime.createCase) and prospect-won.ts (from `prospect.won`, raised only by winProspect after FO-13c's clearForWin);
//      createCase's callers are the persona route, Demo › Sample case and the story's sample case (all refused in
//      production by the gate, which reads `by`) and openCaseFromOffer (staff; through prospect-won.ts's door). A new writer
//      or caller fails this suite.
// US$0, no model call, never :4400. Starts and stops its own copy:
//   tsx --tsconfig api/tsconfig.json tests/check_qa621_persona_door_production.ts [name=qa621p] [port=4474]   (from studio/)
import { execFileSync } from "node:child_process";
import { randomBytes, randomUUID } from "node:crypto";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, relative } from "node:path";

const NAME = process.argv[2] ?? "qa621p", PORT = Number(process.argv[3] ?? 4474);
if (PORT === 4400) { console.log("refused: never the demo on :4400"); process.exit(2); }
const STUDIO = join(import.meta.dirname, ".."), DB = `xr_studio_${NAME}`, BASE = `http://127.0.0.1:${PORT}`;
let pass = 0, fail = 0;
const ok = (name: string, c: unknown, detail?: unknown) => { c ? pass++ : fail++; console.log(`${c ? "PASS" : "FAIL"}  ${name}${!c && detail !== undefined ? ` — ${JSON.stringify(detail).slice(0, 500)}` : ""}`); };
const iso = (action: string, args: string[] = []) => execFileSync("zsh", [join(STUDIO, "tools", "isolated.sh"), NAME, String(PORT), action, ...args], { cwd: STUDIO, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: 300_000 });
const sql = (q: string) => execFileSync("psql", ["-h", "127.0.0.1", "-p", "54329", "-U", "xr_studio", "-d", DB, "-XAtq", "-c", q], { encoding: "utf8" }).trim();
const counts = () => sql("select (select count(*) from case_client) || ':' || (select count(*) from runtime_case)");
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- API answers are read loosely, as in the other checks
const api = async (method: string, path: string, body?: unknown, actor?: string): Promise<{ status: number; body: any }> => {
  const r = await fetch(`${BASE}/api${path}`, { method, headers: { "content-type": "application/json", connection: "close", ...(actor ? { "x-actor": actor } : {}) }, body: body === undefined ? undefined : JSON.stringify(body), signal: AbortSignal.timeout(180_000) });
  return { status: r.status, body: await r.json().catch(() => null) };
};
const ready = async () => { for (let i = 0; i < 60; i++) { const s = await fetch(`${BASE}/api/health/ready`, { signal: AbortSignal.timeout(5_000) }).then((r) => r.status, () => 0); if (s === 200) return true; await new Promise((r) => setTimeout(r, 1_000)); } return false; };
const rand = (n: number) => randomBytes(n).toString("hex").slice(0, n);
/** Every setting a production configuration requires, made by this run (as check_pf24w_environment.ts). DATABASE_URL
 *  is the copy's own (isolated.sh); PLATFORM_IDENTITY is unset (no staff sign-in on this server; local is refused in production). */
const production = () => Object.entries({
  PLATFORM_ENVIRONMENT: "production", PLATFORM_COGNITO_USER_POOL_ID: `ca-central-1_${rand(9)}`, PLATFORM_COGNITO_CLIENT_ID: rand(26),
  PLATFORM_STRIPE_SECRET_KEY: ["sk", "test", rand(32)].join("_"), PLATFORM_STRIPE_WEBHOOK_SECRET: ["whsec", rand(32)].join("_"),
  PLATFORM_SES_REGION: "ca-central-1", PLATFORM_BOLDSIGN_API_KEY: rand(40),
  PLATFORM_ZOOM_CLIENT_ID: rand(22), PLATFORM_ZOOM_CLIENT_SECRET: rand(32), PLATFORM_ZOOM_WEBHOOK_SECRET_TOKEN: rand(22),
  PLATFORM_SECRET_BOX_KEYS: `1:${randomBytes(32).toString("base64")}`, PLATFORM_SECRET_BOX_KEY_VERSION: "1",
  PLATFORM_FILES: "local",   // PF-F1b: production names its file store (unset stops the start-up); this suite's subject is the persona door
}).map(([k, v]) => `${k}=${v}`);

// The Open a case dialog's body (the web app's runtime/cases.tsx): no clientId, so the opening would make a new client.
const dialog = (combinationId: string) => ({ combinationId, clientActor: "user-P", principal: { displayName: `Persona ${rand(6)}` }, idempotencyKey: randomUUID() });
let vv = "";
try {
  // 1. local: the control.
  iso("start", ["--ttl", "20", "PLATFORM_IDENTITY=local"]);
  ok("setup: the local copy answers /api/health/ready", await ready());
  const load = await api("POST", "/demo/load", { sample: "configured" }, "user-A");
  vv = sql("select c.id from combination c where c.combination_key = 'vv.single' and exists (select 1 from config_release r where r.combination_id = c.id)");
  ok("setup: the configured sample is loaded and the Visitor visa is released", load.status < 300 && !!vv, { status: load.status, vv });
  const before = counts();
  const local = await api("POST", "/runtime/cases", dialog(vv), "user-O");
  const [c0, k0] = before.split(":").map(Number), [c1, k1] = counts().split(":").map(Number);
  ok("control (local): the dialog's body on the persona route opens a case with a new client (201; the body is valid and the door is open locally)", local.status === 201 && c1 === c0 + 1 && k1 === k0 + 1, { status: local.status, before, after: counts(), detail: local.body?.detail });

  // 2. production, the same database.
  iso("restart", ["--ttl", "20", ...production()]);
  ok("setup: the same copy restarts with PLATFORM_ENVIRONMENT=production and answers /api/health/ready", await ready(), readTail());
  const seen = await api("GET", "/health/ready");
  ok("setup: the copy runs as production (its readiness answer names it, or the local sign-in door is closed)", seen.status === 200 && (JSON.stringify(seen.body ?? {}).includes("production") || (await api("POST", "/platform/session/local", {})).status === 403), seen.body);
  const p0 = counts();
  const persona = await api("POST", "/runtime/cases", dialog(vv), "user-O");
  ok("QA-621 (production): the persona route POST /api/runtime/cases is refused 403 SIMULATED_PERSON_REFUSED", persona.status === 403 && persona.body?.code === "SIMULATED_PERSON_REFUSED", { status: persona.status, body: persona.body });
  ok("QA-621 (production): the refused persona opening writes nothing (no client, no case)", counts() === p0, { before: p0, after: counts() });
  const withClient = await api("POST", "/runtime/cases", { ...dialog(vv), clientId: sql("select id from case_client order by client_number desc limit 1") }, "user-O");
  ok("QA-621 (production): the persona route is refused even when it names an existing client (the door, not the branch)", withClient.status === 403 && withClient.body?.code === "SIMULATED_PERSON_REFUSED" && counts() === p0, { status: withClient.status, code: withClient.body?.code });
  const sample = await api("POST", "/demo/sample-case", { combinationId: vv }, "user-A");
  // Demo › Sample case wraps an opening's refusal in its own 409 ("The Sample case was not opened: …"), carrying the gate's words.
  ok("QA-621 (production): Demo › Sample case (createCase as a simulated officer) is refused by the gate and writes nothing", [403, 409].includes(sample.status) && /door is closed in production/.test(String(sample.body?.detail)) && counts() === p0, { status: sample.status, body: sample.body, after: counts() });
  const someClient = sql("select id from case_client order by client_number limit 1");
  const signedIn = await api("POST", `/runtime/clients/${someClient}/open-case`, { clientActor: "user-P" }, "user-O");
  ok("QA-621 (production): the signed-in door (open-case from a won client) asks for a staff session; the simulated header gives nothing (401)", signedIn.status === 401 && counts() === p0, { status: signedIn.status, body: signedIn.body });
} finally { try { iso("stop"); } catch { /* the copy stops itself by its ttl */ } }

// 3. The sweep: who writes a client, who opens a case.
const files = (d: string): string[] => readdirSync(d).flatMap((f) => { const p = join(d, f); return statSync(p).isDirectory() ? files(p) : p.endsWith(".ts") ? [p] : []; });
const src = files(join(STUDIO, "api", "src")).map((p) => ({ p: relative(STUDIO, p), t: readFileSync(p, "utf8") }));
const where = (re: RegExp) => src.flatMap(({ p, t }) => t.split("\n").flatMap((l, i) => (re.test(l) && !/^\s*(\/\/|\*|\/\*\*)/.test(l) ? [`${p}:${i + 1}`] : []))).map((s) => s.replace(/:\d+$/, ""));
const uniq = (a: string[]) => [...new Set(a)].sort();
ok("sweep: a case_client row is written only by api/src/clients.ts (newClient) and api/src/case-clients/prospect-won.ts (a won prospect)",
  JSON.stringify(uniq(where(/\bcaseClient\.(create|createMany|upsert)\(|insert\s+into\s+case_client\b/i))) === JSON.stringify(["api/src/case-clients/prospect-won.ts", "api/src/clients.ts"]), uniq(where(/\bcaseClient\.(create|createMany|upsert)\(|insert\s+into\s+case_client\b/i)));
ok("sweep: newClient is called only by api/src/runtime.ts (Runtime.createCase)", JSON.stringify(uniq(where(/\bnewClient\(/).filter((p) => p !== "api/src/clients.ts"))) === JSON.stringify(["api/src/runtime.ts"]), uniq(where(/\bnewClient\(/)));
ok("sweep: runtime_case is written only by api/src/runtime.ts (Runtime.createCase)", JSON.stringify(uniq(where(/\.case\.(create|createMany|upsert)\(|insert\s+into\s+runtime_case\b/i))) === JSON.stringify(["api/src/runtime.ts"]), uniq(where(/\.case\.(create|createMany|upsert)\(|insert\s+into\s+runtime_case\b/i)));
const callers = uniq(where(/\.createCase\(|createCase: \(/).filter((p) => !/\basync createCase\(/.test(p)));
ok("sweep: createCase's callers are the persona route and openCaseFromOffer (runtime.ts, through prospect-won.ts's door), Demo › Sample case and the story (sample-case.ts) only",
  JSON.stringify(callers) === JSON.stringify(["api/src/case-clients/prospect-won.ts", "api/src/runtime.ts", "api/src/sample-case.ts"]), callers);
const runtime = readFileSync(join(STUDIO, "api", "src", "runtime.ts"), "utf8");
ok("sweep: openCaseFromOffer is the only caller that passes a staff:<id> actor word to createCase (the gate's one way through in production)",
  (runtime.match(/this\.createCase\([^)]*`staff:\$\{ctx\.staffId\}`\)/g) ?? []).length === 1 && /async openCaseFromOffer\(ctx: StaffContext/.test(runtime), null);
// Raised = written to the outbox (module_event); prospect-won.ts's catch-up only replays rows already there.
const raised = uniq(where(/moduleEvent\.create\(.*EVENT\.PROSPECT_WON\b/));
ok("sweep: `prospect.won` is raised (written to the outbox) only by winProspect, after FO-13c's clearForWin",
  JSON.stringify(raised) === JSON.stringify(["api/src/front-office/sales/prospects.ts"])
  && /await clearForWin\([^;]*\);[\s\S]*?type: EVENT\.PROSPECT_WON/.test(readFileSync(join(STUDIO, "api", "src", "front-office", "sales", "prospects.ts"), "utf8")), raised);

function readTail() { try { return readFileSync(join(STUDIO, "var", `isolated-${NAME}`, "api.log"), "utf8").slice(-600); } catch { return ""; } }
console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
